mapper.select:
SELECT SOLUTIONID,SOLUTIONCODE,SOLUTIONNAME,sta.REALNAME, sta.STAFFID,s.CREATEDATE,s.ENDDATE,ST.REALNAME zgname,ST.STAFFID zgstaffid,s.RUNSTATUS,s.ZGSTATUS FROM TBL_NBSJ_REFORM_SOLUTION s LEFT JOIN TBL_STAFF sta on s.STAFFID=STA.STAFFID LEFT JOIN TBL_STAFF st ON s.reformuserid = ST.STAFFID
and s.reformuserid= #{orgId} and s.RUNSTATUS= #{type}
and (s.SOLUTIONID in ( select DISTINCT SOLUTIONID from TBL_NBSJ_REFOPM where (status=1 or status=2) and PERONINCHARGE= #{orgId}) or (s.reformuserid= #{orgId} and s.RUNSTATUS < 6 and s.RUNSTATUS>1))
and s.RUNSTATUS=6 and s.ORGID in (select DISTINCT ORGID from TBL_ORGANIZATION where FATHERORGID=#{orgId} OR ORGID=#{orgId})
and s.ORGID in (select DISTINCT ORGID from TBL_ORGANIZATION where FATHERORGID=#{orgId} OR ORGID=#{orgId})
and SOLUTIONCODE like concat(concat('%',#{re.solutioncode}),'%')
and SOLUTIONNAME like concat(concat('%',#{solutionname}),'%')
and runstatus = #{re.runstatus}
and s.STAFFID = #{re.createStaff.staffid}
ORDER BY SOLUTIONID DESC
